package com.atlasiq.twin;
import jakarta.enterprise.context.ApplicationScoped;import java.util.*;
@ApplicationScoped public class AgentGuardService {private final ArchitectureSimulationService simulation;private final ArchitectureBudgetService budgets;public AgentGuardService(ArchitectureSimulationService s,ArchitectureBudgetService b){simulation=s;budgets=b;}public GuardResult preflight(String analysisId,List<String>targets){var sim=simulation.simulate(analysisId,new ArchitectureSimulationService.Scenario(targets,4,"agent preflight"));List<String>reasons=new ArrayList<>();if(sim.riskScore()>=70)reasons.add("high simulated blast radius");if(sim.affectedComponents().size()>10)reasons.add("change crosses more than 10 architecture components");return new GuardResult(reasons.isEmpty()?"SAFE":"REQUIRES_REVIEW",sim.riskScore(),sim.affectedComponents().stream().map(x->x.id()).toList(),List.copyOf(reasons));}public ArchitectureBudgetService.Result validateChange(String base,String head,ArchitectureBudgetService.Budget budget){return budgets.evaluate(base,head,budget);}public record GuardResult(String decision,int riskScore,List<String>affectedComponents,List<String>reasons){}}
